appears_as_source = 0
appears_as_dest = 0

for line in edges_text.split('\n'):
    line = line.strip()
    if '->' in line:
        parts = line.split('->')
        source = parts[0].strip()
        dest = parts[1].strip()
        if source == target:
            appears_as_source += 1
        if dest == target:
            appears_as_dest += 1

print(f"Node {target} appears as source: {appears_as_source} times")
print(f"Node {target} appears as destination: {appears_as_dest} times")

